import{_ as o,o as i,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"3.3.1 View User Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-1-view-user-profile/spec.md","filePath":"feature/profile/3-3-1-view-user-profile/spec.md"}'),r={name:"feature/profile/3-3-1-view-user-profile/spec.md"};function s(n,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-3-1-view-user-profile" tabindex="-1">3.3.1 View User Profile <a class="header-anchor" href="#_3-3-1-view-user-profile" aria-label="Permalink to &quot;3.3.1 View User Profile&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user opens the Profile screen at <code>/profile</code>.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any authenticated user (role <code>USER</code>); a user reads only their own profile.</li><li><strong>Purpose:</strong> Display the personal information the system holds for the signed-in user, so the user can verify it.</li><li><strong>Interface:</strong> The Profile screen at <code>/profile</code> (<code>pages/profile/index.tsx</code>), a single page that combines the read-only view and the edit form (Edit toggles the same section into edit mode — see FR 3.3.2 for the edit behavior). In view mode, every field is rendered as text and cannot be edited — the Edit button switches the section into edit mode.</li><li><strong>Data Processing:</strong> The system resolves the caller&#39;s identity from the access token only (no user identifier is accepted from the caller), loads the matching user record, resolves the system role, resolves the current workspace, and derives the timezone and notification preferences from the preferences data stored on that user record. No data is modified.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Profile Screen (<code>/profile</code>, view mode):</p><ul><li>Header: page title &quot;Profile&quot;.</li><li>Top card: avatar image (or default initials avatar when none is set), full name, email address, a &quot;Verified&quot; badge, and an Edit button that switches the section into edit mode.</li><li>Below, in a two-column grid: system role, phone number (with a change/add-phone link opening the Link Phone dialog), member-since date, last-login date, job title (<code>professionalTitle</code>), working language, timezone, bio, and portfolio URLs (rendered as a list of clickable links) — each field showing an empty-state placeholder when not set.</li><li>Side panel: Danger Zone card with a Deactivate Account button (opens a confirmation dialog; separate flow, not part of this FR).</li><li>Buttons: Edit — switches the profile card into edit mode (FR 3.3.2).</li><li>Footer: none.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> None — the signed-in user&#39;s identity is derived from the access token; the caller cannot supply another user&#39;s identifier.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> <code>users</code> (userId, email, fullName, avatarUrl, phone, professionalTitle, bio, portfolioUrls JSON array, workingLanguage, preferences JSON holding the timezone and notification preferences, createdAt); <code>user_system_roles</code> (system role); <code>workspace_members</code> (workspaceId).</li><li><strong>Output:</strong> The complete profile field set — <code>userId</code>, <code>email</code>, <code>fullName</code>, <code>avatarUrl</code>, <code>phone</code>, <code>role</code>, <code>workspaceId</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code> (array of strings), <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>, <code>createdAt</code>.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-18:</strong> <code>/users/me</code> resolves identity from the JWT principal only — no <code>userId</code> path/query parameter, so a user can never read another user&#39;s profile.</li><li><strong>Implementation note (no dedicated global BR):</strong> <code>role</code> is read from the user&#39;s system role records; when no role record exists, <code>role</code> defaults to <code>USER</code>. <code>workspaceId</code> is taken from the token; when the token carries none, the system falls back to the user&#39;s first active workspace membership. <code>timezone</code> and <code>notificationPreferences</code> have no dedicated columns — both are stored inside the JSON <code>preferences</code> field of the user record.</li><li><strong>Implementation note (no dedicated global BR):</strong> <code>avatarUrl</code> is empty when the user has never uploaded an avatar; the interface then shows a default initials avatar. This is not an error.</li><li><strong>Implementation note (no dedicated global BR):</strong> <code>professionalTitle</code>, <code>bio</code>, and <code>workingLanguage</code> are plain nullable columns on the user record; <code>portfolioUrls</code> is stored as a JSON-serialized string column and deserialized to a list of strings for the response (an unparsable or blank value returns an empty list, never an error).</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>No request body is accepted; validation is limited to authentication.</li><li>Missing, expired, or invalid access token → 401 <code>UNAUTHORIZED</code>, Display: MSG22.</li><li>The user record no longer exists (theoretical: a valid token held for a deleted user) → 404 <code>USER_NOT_FOUND</code>, Display: MSG38.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The signed-in user opens <code>/profile</code>.</li><li>The application requests the signed-in user&#39;s own profile.</li><li>The system resolves the caller&#39;s identity from the access token and loads the matching user record.</li><li>The system resolves the system role, applying the default when no role record exists.</li><li>The system resolves the current workspace, falling back to the first active workspace membership when the token carries none.</li><li>The system derives <code>timezone</code> and <code>notificationPreferences</code> from the stored preferences data.</li><li>The system returns the complete profile field set.</li><li>The application renders the read-only profile card, showing a default initials avatar when no avatar exists.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Missing, expired, or invalid access token (CR-AUTH-01) → 401 <code>UNAUTHORIZED</code>, toast MSG22. 3.a2: The user signs in again at /login (3.2.2).</li><li>3.b1: The user record no longer exists (BR-18) → 404 <code>USER_NOT_FOUND</code>, toast MSG38. 3.b2: The user is signed out and returned to /login.</li><li>8.a1: No avatar has ever been set → <code>avatarUrl</code> is empty; not an error. 8.a2: The application shows a default initials avatar in place of the avatar image.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The signed-in user&#39;s profile is displayed with the values currently stored in the system.</li><li>No data is changed; the operation is read-only.</li></ul>',22)])])}const p=o(r,[["render",s]]);export{f as __pageData,p as default};
